import{_ as e,c as r,o,ag as s}from"./chunks/framework.DCv_I274.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md","lastUpdated":null}'),d={name:"reference/glossary.md"};function n(a,t,i,g,l,c){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Access token</strong></td><td>Short-lived JWT sent as <code>Authorization: Bearer ...</code> on every API call</td></tr><tr><td><strong>API</strong></td><td>Application Programming Interface: a way for programs to talk; here, HTTP + JSON</td></tr><tr><td><strong>Artisan</strong></td><td>Laravel&#39;s command-line tool (<code>php artisan ...</code>)</td></tr><tr><td><strong>Blade</strong></td><td>Laravel&#39;s HTML template engine (<code>.blade.php</code>)</td></tr><tr><td><strong>Catalogue</strong></td><td>The list of actions each sub-module offers (<code>system_sub_modules_actions</code>)</td></tr><tr><td><strong>Composer</strong></td><td>PHP&#39;s package manager (<code>composer.json</code>, <code>vendor/</code>)</td></tr><tr><td><strong>Controller</strong></td><td>Class that turns an HTTP request into a service call and the result into a response</td></tr><tr><td><strong>CORS</strong></td><td>Browser rule that blocks reading responses from another origin unless the server allows it</td></tr><tr><td><strong>CSRF</strong></td><td>An attack where another site makes your browser send a request with your cookies</td></tr><tr><td><strong>DTO / value object</strong></td><td>Small class that only carries data (<code>ClientInfo</code>, <code>IssuedTokens</code>)</td></tr><tr><td><strong>Eager loading</strong></td><td>Loading relations up front with <code>with()</code> to avoid N + 1 queries</td></tr><tr><td><strong>Eloquent</strong></td><td>Laravel&#39;s ORM: models map to tables</td></tr><tr><td><strong>Envelope</strong></td><td>The standard response shape <code>{ success, message, data }</code></td></tr><tr><td><strong>Factory</strong></td><td>Class that makes fake model data for tests and seeding</td></tr><tr><td><strong>Family</strong></td><td>All refresh-token rows of one login (one device), sharing a <code>family_id</code></td></tr><tr><td><strong>FormRequest</strong></td><td>Class holding the validation rules for one endpoint</td></tr><tr><td><strong>Guard</strong></td><td>Laravel&#39;s &quot;who is the user?&quot; mechanism: <code>web</code> (session) or <code>api</code> (JWT)</td></tr><tr><td><strong>HMAC</strong></td><td>A keyed hash; used to store refresh tokens with a secret pepper</td></tr><tr><td><strong>httpOnly cookie</strong></td><td>A cookie JavaScript cannot read</td></tr><tr><td><strong>Idempotent</strong></td><td>Repeating the request has the same effect as sending it once</td></tr><tr><td><strong>JWT</strong></td><td>JSON Web Token: a signed JSON document (<code>header.payload.signature</code>)</td></tr><tr><td><strong>Middleware</strong></td><td>Code that runs before/after a controller: auth, permissions, throttling, logging</td></tr><tr><td><strong>Migration</strong></td><td>A versioned schema change written in PHP</td></tr><tr><td><strong>Model</strong></td><td>Eloquent class for one table</td></tr><tr><td><strong>Module</strong></td><td>One feature: route file + request + controller + service + resource (+ model)</td></tr><tr><td><strong>N + 1 problem</strong></td><td>One query for a list plus one per row for a relation</td></tr><tr><td><strong>ORM</strong></td><td>Object-relational mapper: work with objects instead of SQL</td></tr><tr><td><strong>Origin</strong></td><td>Scheme + host + port, e.g. <code>http://localhost:5173</code></td></tr><tr><td><strong>Pepper</strong></td><td>Server-side secret mixed into a hash, kept out of the database</td></tr><tr><td><strong>Pivot table</strong></td><td>Table joining two others in a many-to-many relation</td></tr><tr><td><strong>RBAC</strong></td><td>Role-based access control: permissions granted to groups, users in groups</td></tr><tr><td><strong>Refresh token</strong></td><td>Long-lived random token that gets new access tokens; httpOnly cookie</td></tr><tr><td><strong>Resource</strong></td><td>Class that shapes a model into JSON</td></tr><tr><td><strong>REST</strong></td><td>Conventions for HTTP APIs: resources in URLs, meaning in methods and status codes</td></tr><tr><td><strong>Rotation</strong></td><td>Every refresh replaces the refresh token; the old one becomes invalid</td></tr><tr><td><strong>Seeder</strong></td><td>Class that inserts initial data</td></tr><tr><td><strong>Service</strong></td><td>Class holding a feature&#39;s business logic, queries, transactions and logging</td></tr><tr><td><strong>Service container</strong></td><td>Laravel&#39;s object builder that injects dependencies</td></tr><tr><td><strong>Signed URL</strong></td><td>URL with a signature and expiry that the server can verify</td></tr><tr><td><strong>Soft delete</strong></td><td>Marking a row deleted (<code>deleted_at</code>) instead of removing it</td></tr><tr><td><strong>SPA</strong></td><td>Single-page application: a JavaScript frontend that calls an API</td></tr><tr><td><strong>Sub-module</strong></td><td>One screen inside a module (Campus Setup, Access Rights); permissions are per sub-module</td></tr><tr><td><strong>Transaction</strong></td><td>A group of database writes that succeed or fail together</td></tr><tr><td><strong>Vite</strong></td><td>The frontend build tool Laravel uses for CSS/JS</td></tr></tbody></table>',2)])])}const p=e(d,[["render",n]]);export{u as __pageData,p as default};
